import{_ as t,o,c as r,ag as a}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/sheets/edit-and-format-edit-panel-mobile.png",l="/docs/images/sheets/edit-and-format-more-formats.png",u=JSON.parse('{"title":"Edit and format cells","description":"Enter, fill, move, and find data in a sheet, and format cells with number formats, colors, borders, and alignment.","frontmatter":{"title":"Edit and format cells","description":"Enter, fill, move, and find data in a sheet, and format cells with number formats, colors, borders, and alignment.","type":"how-to"},"headers":[],"relativePath":"sheets/edit-and-format.md","filePath":"sheets/edit-and-format.md"}'),s={name:"sheets/edit-and-format.md"};function i(c,e,d,h,g,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="edit-and-format-cells" tabindex="-1">Edit and format cells <a class="header-anchor" href="#edit-and-format-cells" aria-label="Permalink to &quot;Edit and format cells&quot;">​</a></h1><p>Enter, fill, move, and find data in a sheet, and format cells with number formats, colors, borders, and alignment.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. With a viewer link the grid is read-only and the toolbar is hidden.</li><li>A sheet tab has 1,000,000 rows and 18,278 columns (<strong>A</strong> to <strong>ZZZ</strong>).</li></ul></div><h2 id="enter-and-edit-a-cell" tabindex="-1">Enter and edit a cell <a class="header-anchor" href="#enter-and-edit-a-cell" aria-label="Permalink to &quot;Enter and edit a cell&quot;">​</a></h2><ol><li>Click a cell.</li><li>Type a value or a formula. Typing replaces what the cell holds.</li><li>Press <code>Enter</code> to save and move down, or <code>Tab</code> to save and move right.</li></ol><p>To change part of a cell instead of replacing it, select the cell and press <code>F2</code>, or double-click it. You can also edit the selected cell in the formula bar above the grid. Press <code>Escape</code> to cancel an edit.</p><p>To start a new line inside a cell while editing, press <code>Alt+Enter</code> (Mac: <code>Option+Enter</code>).</p><p>To clear the selected cells, press <code>Delete</code> or <code>Backspace</code>, or right-click and select <strong>Delete values</strong>.</p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><ol><li>Double-tap a cell. An edit panel opens at the bottom of the screen with the cell&#39;s name, such as <strong>B2</strong>.</li><li>Type the new value.</li><li>Tap the check mark (<strong>Confirm editing</strong>) to save, or the X (<strong>Cancel editing</strong>) to discard.</li></ol><p>The formula bar and the Name box are hidden on a phone.</p><p><img src="'+n+'" alt="Phone edit panel at the bottom of the screen for cell B2, with cancel and confirm buttons"></p><h2 id="fill-a-series-or-a-formula" tabindex="-1">Fill a series or a formula <a class="header-anchor" href="#fill-a-series-or-a-formula" aria-label="Permalink to &quot;Fill a series or a formula&quot;">​</a></h2><ol><li>Select the cells to copy from, for example <code>1</code> and <code>2</code> in <strong>A1:A2</strong>.</li><li>Drag the fill handle, the small square at the bottom-right corner of the selection, across the cells to fill.</li></ol><p>Numbers continue their trend (<code>3</code>, <code>4</code>, <code>5</code>, …). Text repeats, and formulas adjust their references to each new row or column.</p><p>To copy the top cell of a selection down through the rest of it, press <code>⌘+D</code> / <code>Ctrl+D</code>. To copy the leftmost cell to the right, press <code>⌘+R</code> / <code>Ctrl+R</code>.</p><p>On a phone the fill handle is hidden.</p><h2 id="move-copy-and-paste-cells" tabindex="-1">Move, copy, and paste cells <a class="header-anchor" href="#move-copy-and-paste-cells" aria-label="Permalink to &quot;Move, copy, and paste cells&quot;">​</a></h2><ul><li><strong>Move:</strong> select cells, then drag the selection&#39;s border to a new place.</li><li><strong>Copy or cut:</strong> press <code>⌘+C</code> / <code>Ctrl+C</code> or <code>⌘+X</code> / <code>Ctrl+X</code>, or right-click and select <strong>Copy</strong> or <strong>Cut</strong>.</li><li><strong>Paste:</strong> select the top-left target cell and press <code>⌘+V</code> / <code>Ctrl+V</code>, or right-click and select <strong>Paste</strong>.</li></ul><p>Tab-separated text pasted from another spreadsheet or a text editor fills one cell per value. Press <code>Escape</code> to clear the dashed border around copied cells.</p><p>On a phone, touch and hold a cell to open the same menu.</p><h2 id="go-to-a-cell-or-range" tabindex="-1">Go to a cell or range <a class="header-anchor" href="#go-to-a-cell-or-range" aria-label="Permalink to &quot;Go to a cell or range&quot;">​</a></h2><ol><li>Click the Name box, at the left end of the formula bar. It shows the current selection.</li><li>Type a cell or range: <code>C3</code>, <code>B2:D4</code>, whole columns such as <code>A:C</code>, or whole rows such as <code>2:5</code>.</li><li>Press <code>Enter</code>.</li></ol><p>The grid scrolls to the target and selects it. If the text isn&#39;t a valid reference, the Name box goes back to the current selection. Press <code>Escape</code> to leave it without moving.</p><h2 id="find-values" tabindex="-1">Find values <a class="header-anchor" href="#find-values" aria-label="Permalink to &quot;Find values&quot;">​</a></h2><ol><li>Press <code>⌘+F</code> / <code>Ctrl+F</code>. The find bar opens.</li><li>Type the text to find. The bar shows the match count, such as <code>2/5</code>.</li><li>Press <code>Enter</code> for the next match or <code>Shift+Enter</code> for the previous one. You can also click <strong>Previous match</strong> and <strong>Next match</strong>.</li><li>Press <code>Escape</code> to close the bar.</li></ol><p>Find searches the current tab, ignores case, and matches values as they appear in the cell, including their number format.</p><h2 id="open-links-in-a-cell" tabindex="-1">Open links in a cell <a class="header-anchor" href="#open-links-in-a-cell" aria-label="Permalink to &quot;Open links in a cell&quot;">​</a></h2><p>Every web address or email address you type in a cell becomes a link, even when the cell holds other text or several links.</p><ul><li><strong>Open a link:</strong> hold <code>⌘</code> / <code>Ctrl</code> and click it. In a sheet you can only view, a plain click opens it.</li><li><strong>Open every link in the selected cell:</strong> press <code>Alt+Enter</code> (Mac: <code>Option+Enter</code>) while not editing.</li><li><strong>See or copy a link:</strong> point to the cell. A card lists the cell&#39;s links, each with a copy button.</li></ul><h2 id="format-numbers-currency-and-dates" tabindex="-1">Format numbers, currency, and dates <a class="header-anchor" href="#format-numbers-currency-and-dates" aria-label="Permalink to &quot;Format numbers, currency, and dates&quot;">​</a></h2><ol><li>Select the cells.</li><li>Click a format in the toolbar: <ul><li><strong>Format as currency</strong> applies your local currency. Its tooltip names it, for example <strong>Format as currency (USD)</strong>.</li><li><strong>Format as percent</strong> shows <code>0.25</code> as <code>25.00%</code>.</li><li><strong>Decrease decimal places</strong> and <strong>Increase decimal places</strong> change the digits after the decimal point.</li></ul></li><li>For other formats, click <strong>More formats</strong> (the <strong>123 ▾</strong> menu) and select one.</li></ol><p><strong>More formats</strong> lists <strong>Plain text</strong>, <strong>Number</strong>, <strong>Percent</strong>, <strong>Scientific</strong>, <strong>Accounting</strong>, <strong>Financial</strong>, <strong>Currency</strong>, <strong>Currency rounded</strong>, <strong>Date</strong>, <strong>Time</strong>, and <strong>Date time</strong>. Every entry except <strong>Plain text</strong> shows a preview. When your local currency isn&#39;t the US dollar, the currency entries name it, such as <strong>Currency (EUR)</strong>, and a separate <strong>Currency (USD)</strong> entry is added. <strong>Currency rounded</strong> is left out for a currency without decimal places, such as the yen.</p><p><img src="'+l+'" alt="More formats menu listing Plain text through Date time, with a sample value beside each format"></p><p>A currency format keeps the currency you applied. Collaborators in other countries see the same currency, not their own.</p><h3 id="on-a-phone-1" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone-1" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>Tap ⋮ (<strong>More formatting options</strong>) at the right end of the toolbar. The <strong>Format</strong> group has currency, <strong>Percent</strong>, the decimal controls, <strong>Plain text</strong>, <strong>Number</strong>, and <strong>Date</strong>.</p><h2 id="style-text-and-fill-cells" tabindex="-1">Style text and fill cells <a class="header-anchor" href="#style-text-and-fill-cells" aria-label="Permalink to &quot;Style text and fill cells&quot;">​</a></h2><ol><li>Select the cells.</li><li>Use the toolbar: <ul><li><strong>Bold</strong> (<code>⌘+B</code> / <code>Ctrl+B</code>), <strong>Italic</strong> (<code>⌘+I</code> / <code>Ctrl+I</code>), <strong>Underline</strong> (<code>⌘+U</code> / <code>Ctrl+U</code>), and <strong>Strikethrough</strong> (<code>⌘+Shift+S</code> / <code>Ctrl+Shift+S</code>)</li><li><strong>Text color</strong>: pick a swatch, or <strong>Reset</strong> for the default color</li><li><strong>Fill color</strong>: pick a swatch, or <strong>None</strong> to remove the fill</li></ul></li></ol><p>On a phone, <strong>Underline</strong> and <strong>Strikethrough</strong> are in the ⋮ menu.</p><h2 id="add-borders" tabindex="-1">Add borders <a class="header-anchor" href="#add-borders" aria-label="Permalink to &quot;Add borders&quot;">​</a></h2><ol><li>Select the cells.</li><li>Click <strong>Cell borders</strong> in the toolbar.</li><li>Select <strong>All borders</strong>, <strong>Outer border</strong>, <strong>Inner borders</strong>, <strong>Top border</strong>, <strong>Bottom border</strong>, <strong>Left border</strong>, or <strong>Right border</strong>.</li></ol><p>To remove borders, select <strong>Clear borders</strong>. On a phone, the same options are under <strong>Borders</strong> in the ⋮ menu.</p><h2 id="align-and-merge-cells" tabindex="-1">Align and merge cells <a class="header-anchor" href="#align-and-merge-cells" aria-label="Permalink to &quot;Align and merge cells&quot;">​</a></h2><ol><li>Select the cells.</li><li>Click <strong>Horizontal align</strong> and select <strong>Left</strong>, <strong>Center</strong>, or <strong>Right</strong>.</li><li>Click <strong>Vertical align</strong> and select <strong>Top</strong>, <strong>Middle</strong>, or <strong>Bottom</strong>.</li></ol><p>To combine the selected cells into one, click <strong>Merge cells</strong> or press <code>⌘+Shift+M</code> / <code>Ctrl+Shift+M</code>. To split them again, select the merged cell and click <strong>Unmerge cells</strong>.</p><p>On a phone, alignment is under <strong>Align</strong> in the ⋮ menu. <strong>Merge cells</strong> stays on the toolbar.</p><h2 id="copy-formatting-with-paint-format" tabindex="-1">Copy formatting with Paint format <a class="header-anchor" href="#copy-formatting-with-paint-format" aria-label="Permalink to &quot;Copy formatting with Paint format&quot;">​</a></h2><ol><li>Select a cell whose formatting you want to copy.</li><li>Click <strong>Paint format</strong> in the toolbar.</li><li>Click a cell, or drag across a range, to apply the formatting.</li></ol><p>Paint format turns off after one use. To stop before applying, click <strong>Cancel paint format</strong>.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>You can&#39;t change the font family or font size of cells.</li><li><strong>Merge cells</strong> is unavailable on a pivot table tab.</li><li>Find has no replace option.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/keyboard-shortcuts.html">Keyboard shortcuts</a> for every editing and formatting key.</li><li><a href="/docs/sheets/conditional-formatting.html">Conditional formatting</a> to format cells that match a rule.</li><li><a href="/docs/sheets/rows-columns-tabs.html">Rows, columns, and tabs</a> to insert, hide, and resize rows and columns.</li><li><a href="/docs/collaborate/comments.html">Comments</a> to discuss a cell with your team.</li></ul>',54)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
